package com.wipro.hibernate;import org.hibernate.*;import java.math.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();Product p=new Product();p.setProductName("Laptop");p.setPrice(new BigDecimal("75000"));s.persist(p);t.commit();System.out.println("Product inserted with generated ID: "+p.getProductId());}HibernateUtil.getSessionFactory().close();}}